var COM = {"0": "<p>Errado. O art. 31, § 3º inclui arranjos abertos e fechados, públicos e privados, mesmo os não sujeitos à regulação do BCB.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "1": "<p>Certo. Art. 31, caput.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "2": "<p>Certo. Art. 32, § 1º, I e II, nova redação.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "3": "<p>Errado. O art. 32, § 2º-A permite optar por não transmitir; nesse caso o fornecedor ou a plataforma inclui a vinculação no documento fiscal eletrônico.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "4": "<p>Errado. Art. 33, § 2º, I: é vedada a aplicação do simplificado a apenas um dos tributos.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "5": "<p>Errado. Art. 33, § 2º, III: não guardará relação com os débitos efetivamente incidentes.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "6": "<p>Certo. Art. 33, § 2º-A, incluído pela LC 227/2026.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "7": "<p>Errado. Art. 34, III: não altera a obrigação.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "8": "<p>Certo. Art. 35, § 1º.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "9": "<p>Errado. O art. 36 trata de opção do adquirente do regime regular, quando o instrumento de pagamento não permite a segregação.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "10": "<p>Certo. Art. 36, § 3º, I.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "11": "<p>Errado. Art. 38, I exige que a operação não tenha gerado crédito.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "12": "<p>Certo. Art. 38, II.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "13": "<p>Certo. Art. 39, § 2º.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "14": "<p>Certo. Art. 39, § 5º.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "15": "<p>Errado. Art. 39, § 8º: não afasta a fiscalização posterior.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "16": "<p>Certo. Art. 39, § 10, I.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "17": "<p>Errado. Aplica-se se o pagamento ocorrer a partir do primeiro dia do segundo mês seguinte ao do pedido.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "18": "<p>Certo. Art. 42, § 1º.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "19": "<p>Errado. Art. 42, caput: consolida as operações de todos os estabelecimentos.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "20": "<p>Certo. Art. 41, §§ 3º e 4º.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "21": "<p>Errado. Art. 45, § 4º: implica confissão e constitui o crédito.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "22": "<p>Certo. Art. 46, § 4º.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "23": "<p>Certo. Art. 46, § 8º.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>"};
